package com.shopsphere.controller;import com.shopsphere.model.*;import com.shopsphere.repository.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/orders")public class OrderController{private final OrderRepository orders;private final UserRepository users;private final ProductRepository products;public OrderController(OrderRepository o,UserRepository u,ProductRepository p){orders=o;users=u;products=p;}record ItemRequest(Long productId,Integer quantity){}record PlaceRequest(List<ItemRequest> items,String paymentMethod){}record StatusRequest(OrderStatus status){}@GetMapping @PreAuthorize("hasRole('ADMIN')")public List<ShopOrder> all(){return orders.findAllByOrderByCreatedAtDesc();}@GetMapping("/my")public List<ShopOrder> mine(Authentication a){AppUser u=users.findByEmail(a.getName()).orElseThrow();return orders.findByUserIdOrderByCreatedAtDesc(u.getId());}@PostMapping @Transactional public ShopOrder place(@RequestBody PlaceRequest r,Authentication a){if(r.items()==null||r.items().isEmpty())throw new IllegalArgumentException("Cart is empty");ShopOrder o=new ShopOrder();o.setUser(users.findByEmail(a.getName()).orElseThrow());o.setPaymentMethod(r.paymentMethod()==null?"DEMO_ON_DELIVERY":r.paymentMethod());double total=0;for(ItemRequest i:r.items()){if(i.quantity()==null||i.quantity()<1)throw new IllegalArgumentException("Invalid quantity");Product p=products.findById(i.productId()).orElseThrow(()->new IllegalArgumentException("Product not found"));if(p.getStock()<i.quantity())throw new IllegalArgumentException("Not enough stock: "+p.getName());p.setStock(p.getStock()-i.quantity());products.save(p);o.getItems().add(new OrderItem(o,p,i.quantity(),p.getPrice()));total+=p.getPrice()*i.quantity();}o.setTotalAmount(total);return orders.save(o);}@PutMapping("/{id}/status")@PreAuthorize("hasRole('ADMIN')")public ShopOrder status(@PathVariable Long id,@RequestBody StatusRequest r){ShopOrder o=orders.findById(id).orElseThrow();o.setStatus(r.status());return orders.save(o);}@DeleteMapping("/{id}")@Transactional public void cancel(@PathVariable Long id,Authentication a){ShopOrder o=orders.findById(id).orElseThrow();AppUser u=users.findByEmail(a.getName()).orElseThrow();if(u.getRole()!=Role.ADMIN&&!o.getUser().getId().equals(u.getId()))throw new org.springframework.security.access.AccessDeniedException("Not your order");if(o.getStatus()==OrderStatus.SHIPPED||o.getStatus()==OrderStatus.DELIVERED)throw new IllegalArgumentException("Order cannot be cancelled after shipping");o.setStatus(OrderStatus.CANCELLED);orders.save(o);}}